#!/usr/bin/env node
// Writes local environment files from the running local Supabase stack
// (`npx supabase status`). Keys of a LOCAL stack are development keys, but they
// are still never committed: the generated files are git-ignored.
//
//   node scripts/supabase-env.mjs            -> .env.test.local (tests)
//   node scripts/supabase-env.mjs --app      -> also .env.local (dev server) if missing
import { execSync } from "node:child_process";
import { existsSync, writeFileSync } from "node:fs";

const raw = execSync("npx supabase status -o json", { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
const s = JSON.parse(raw.slice(raw.indexOf("{")));
const mailpit = s.MAILPIT_URL ?? s.INBUCKET_URL ?? "http://127.0.0.1:54324";

const test = {
  TEST_SUPABASE_URL: s.API_URL,
  TEST_SUPABASE_PUBLISHABLE_KEY: s.PUBLISHABLE_KEY,
  TEST_SUPABASE_SECRET_KEY: s.SECRET_KEY,
  TEST_DATABASE_URL: s.DB_URL,
  TEST_MAILPIT_URL: mailpit,
  STRIPE_WEBHOOK_SECRET: process.env.STRIPE_WEBHOOK_SECRET ?? "whsec_local_development_only_not_a_real_secret",
};
const toEnv = (o) => Object.entries(o).map(([k, v]) => `${k}=${v}`).join("\n") + "\n";
writeFileSync(".env.test.local", `# Generated by scripts/supabase-env.mjs — local development only, do not commit\n${toEnv(test)}`);
console.log("wrote .env.test.local");

if (process.argv.includes("--app") && !existsSync(".env.local")) {
  const app = {
    NEXT_PUBLIC_SITE_URL: "http://localhost:3000",
    NEXT_PUBLIC_SUPABASE_URL: s.API_URL,
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: s.PUBLISHABLE_KEY,
    SUPABASE_SECRET_KEY: s.SECRET_KEY,
    EMAIL_PROVIDER: "smtp",
    SMTP_HOST: "127.0.0.1",
    SMTP_PORT: "54325",
    EMAIL_FROM: '"Tamurt Jobs <no-reply@tamurt.local>"',
    CRON_SECRET: "local-dev-cron-secret-change-me",
    STRIPE_WEBHOOK_SECRET: test.STRIPE_WEBHOOK_SECRET,
  };
  writeFileSync(".env.local", `# Generated by scripts/supabase-env.mjs — local development only\n${toEnv(app)}`);
  console.log("wrote .env.local");
}
